import{z as l,x as s,o as n,c as d,q as t,j as r,D as a,d as A,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"逆向归纳的限度","description":"","frontmatter":{"title":"逆向归纳的限度","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/backward-induction-limits.md","filePath":"econ/backward-induction-limits.md","lastUpdated":1791063341000}'),p={name:"econ/backward-induction-limits.md"};function m(C,E,c,h,P,D){const B=s("Mermaid");return n(),d("div",null,[E[2]||(E[2]=t('<h1 id="逆向归纳的限度" tabindex="-1">逆向归纳的限度 <a class="header-anchor" href="#逆向归纳的限度" aria-label="Permalink to &quot;逆向归纳的限度&quot;">​</a></h1><div class="epigraph"><p>若共同知识理性意味着某些节点走不到，那么「在那些节点上仍按理性玩」就不能从共同知识理性推出来。</p><footer>—— 据 Rosenthal, Games of Perfect Information, Predatory Pricing and the Chain-Store Paradox, Journal of Economic Theory, 1981；Reny, Games and Economic Behavior, 1993 整理</footer></div><p><a href="/econ/trembling-hand">上一课</a>（颤抖手完美）。用子博弈完美与逆向归纳删掉空威胁：有限完美信息、无平局时，路径被从终点往前钉死。缺口是这把刀的认知假设。归纳要求每个节点——包括按归纳根本不该到达的节点——仍有共同知识理性。蜈蚣把冲突写成支付。本课钉限度，不重写 SPE 定义，也不把集合撑到无名氏那么肥。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Rosenthal 蜈蚣：两人交替选「停」或「过」。过则总剩余增大，但停的人拿大头。最后一步，理性人停。倒数第二步预见到对方会停，自己先停……归纳推到第一步就停。路径上的支付远低于「一起过很久再停」。</p><p><span class="marginnote">术语翻译：「逆向归纳」就是从结局倒着推——先想最后一轮对方会怎么做，再据此决定自己倒数第二轮怎么走，像下棋从终局杀法倒推回中局。「共同知识理性」则是「我知道你理性，你也知道我知道你理性」一直叠到无穷层。</span></p><p>若第一步居然过了，共同知识理性已经被证伪：按归纳，理性人不会过。到达之后，对方没有理由继续相信「从此仍按逆向归纳玩」。于是「在未达节点上仍最优」不能从「一开始就是共同知识理性」推出来——Reny 把这点写成：共同信念理性与某些信息集的到达不相容。</p><h3 id="不是实验推翻了定义" tabindex="-1">不是实验推翻了定义 <a class="header-anchor" href="#不是实验推翻了定义" aria-label="Permalink to &quot;不是实验推翻了定义&quot;">​</a></h3><p>SPE 作为策略组合的性质（每个子博弈是纳什）没有自相矛盾。脆的是「共同知识理性 \\(\\Rightarrow\\) 逆向归纳」这条认知命题。实验室里蜈蚣晚停，是对照：人们并不持有归纳所需的那层共同知识。定义仍可用；当作预测则过强。</p><p><span class="marginnote">百足长度越长，第一步停越「不合理」——因为对方只要有一点点可能不是归纳玩家，过的期望就升。McKelvey–Palfrey 的实验沿这条比较静态走。本课要的是逻辑限度，不是估计利他参数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限完美信息树。对照三条陈述：（1）SPE / 逆向归纳策略；（2）共同知识理性（CKR）；（3）在所有节点上的 CKR。有限步、支付无平局时，（1）唯一；（2）在根上可以成立；（3）一旦某偏离节点被到达，与（2）冲突。本课把（1）与（3）拆开。</p><p>实验对照只说明人们未必持有（3），不能用来改（1）的定义。</p><p>Aumann 1995 在另一套认知模型里论证：CKR 仍蕴含逆向归纳。争议在「知识」的运算：到达零概率节点后，能否还说「我知道你理性」。本课不站队选模型，只记录：把归纳当共同知识的推论，依赖于如何处理零概率。</p><p>有同时行动的信息集就不是蜈蚣那种纯完美信息，归纳算法本课不用。</p>',15)),(n(),r(i,null,{default:a(()=>[o(B,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPE%5B%22SPE%EF%BC%9A%E6%AF%8F%E4%B8%AA%E5%AD%90%E5%8D%9A%E5%BC%88%E6%98%AF%E7%BA%B3%E4%BB%80%22%5D%20--%3E%20BI%5B%22%E5%AE%8C%E7%BE%8E%E4%BF%A1%E6%81%AF%EF%BC%9A%E9%80%86%E5%90%91%E5%BD%92%E7%BA%B3%22%5D%0A%20%20BI%20--%3E%20CKR%5B%22%E8%8B%A5%20CKR%20%E5%9C%A8%E6%AF%8F%E4%B8%AA%E8%8A%82%E7%82%B9%E4%B8%8A%22%5D%0A%20%20CKR%20--%3E%20FRAG%5B%22%E5%88%B0%E8%BE%BE%E5%B7%B2%E8%AF%81%E4%BC%AA%20CKR%22%5D%0A%20%20FRAG%20--%3E%20CENT%5B%22%E8%9C%88%E8%9A%A3%EF%BC%9A%E7%AC%AC%E4%B8%80%E6%AD%A5%E5%B0%B1%E8%AF%A5%E5%81%9C%EF%BC%9F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"归纳从终点传向前，用的是「对方在下一节点会理性」。若下一节点只在对方已经不理性时才到达，前提落空。蜈蚣每一步都把「过」写成对归纳的偏离，于是除了终点附近，整条合作枝都活在零概率里。SPE 用策略把这些枝上的行动也规定好；CKR 在根上并不强迫人们去规定一棵「不该存在」的树上的共同知识。",-1)),E[5]||(E[5]=e("p",null,"这与空威胁不同。空威胁是到达之后惩罚者不愿执行，SPE 删得干净。蜈蚣的「早停」在到达之后仍是最优——脆的不是可信性，是「我们怎么会走到需要可信性的地方」。有限重复囚徒困境从终点往前拆合作，是同一逻辑的另一张支付表。",-1)),(n(),r(i,null,{default:a(()=>[o(B,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20END%5B%22%E7%BB%88%E7%82%B9%EF%BC%9A%E7%90%86%E6%80%A7%E8%80%85%E9%80%89%E5%81%9C%22%5D%20--%3E%20P1%5B%22%E5%80%92%E6%95%B0%E7%AC%AC%E4%BA%8C%E6%AD%A5%EF%BC%9A%E9%A2%84%E8%A7%81%E5%AF%B9%E6%96%B9%E5%81%9C%EF%BC%8C%E8%87%AA%E5%B7%B1%E5%85%88%E5%81%9C%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E8%BF%99%E6%9D%A1%E9%A2%84%E8%A7%81%E7%BB%A7%E7%BB%AD%E5%90%91%E5%89%8D%E4%BC%A0%22%5D%0A%20%20P2%20--%3E%20P3%5B%22%E6%AF%8F%E4%B8%80%E6%AD%A5%E3%80%8E%E8%BF%87%E3%80%8F%E9%83%BD%E8%A2%AB%E6%8E%A8%E6%88%90%E5%81%8F%E7%A6%BB%22%5D%0A%20%20P3%20--%3E%20ZERO%5B%22%E5%90%88%E4%BD%9C%E6%9E%9D%E6%95%B4%E4%BD%93%E8%90%BD%E5%85%A5%E9%9B%B6%E6%A6%82%E7%8E%87%22%5D%0A%20%20DEV%5B%22%E8%8B%A5%E6%9C%89%E4%BA%BA%E7%AB%9F%E7%84%B6%E3%80%8E%E8%BF%87%E3%80%8F%E4%BA%86%22%5D%20--%3E%20FALS%5B%22%E3%80%8E%E4%BB%8E%E6%AD%A4%E4%BB%8D%E6%8C%89%E5%BD%92%E7%BA%B3%E7%8E%A9%E3%80%8F%E8%A2%AB%E8%AF%81%E4%BC%AA%22%5D%0A%20%20FALS%20--%3E%20NOB%5B%22%E6%9C%AA%E8%BE%BE%E8%8A%82%E7%82%B9%E4%B8%8A%E7%9A%84%E9%A2%84%E6%B5%8B%E5%A4%B1%E5%8E%BB%E6%94%AF%E6%92%91%22%5D%0A%20%20ZERO%20--%3E%20NOB%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">数字实例：设总奖励从 1 开始，每「过」一次翻倍（1→2→4→8），停在当前步的人拿走四分之三。归纳玩家第一步就停，拿 0.75；一路过到最后再停能拿 6。晚停对双方都好得多，但纯归纳说没人会走到那里——这正是实验里人们「晚停」的 puzzle 所在。</span></p><h3 id="一点点不完全信息就拆掉归纳" tabindex="-1">一点点不完全信息就拆掉归纳 <a class="header-anchor" href="#一点点不完全信息就拆掉归纳" aria-label="Permalink to &quot;一点点不完全信息就拆掉归纳&quot;">​</a></h3><p>若有 \\(\\varepsilon\\) 概率对方是「合作类型」，有限蜈蚣可以从后往前撑住很长的「过」。声誉把零概率节点变成正概率学习。这是后课类型的预告：限度往往用信息不完全来救，而不是把 SPE 丢掉。无限地平线没有终点，归纳不能起步，无名氏走另一条路。</p><p><span class="marginnote">连锁店悖论（Selten）是同一结构的市场版：在位者按归纳应在每一市场容纳，但直觉想「建立狠名」。有限次重复加一点类型，狠名可以是均衡。本课用蜈蚣当纯认知教具，不写进入遏制的支付。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>平局、同时行动信息集、不完美信息，逆向归纳本就不是唯一算法，SPE 仍定义。颤抖手让每个节点以任意小概率被碰到，等于用技术扰动强迫（3），归纳又硬起来——那是 Selten 的选择，不是 CKR 的推论。实验偏离归纳，不能单独用来否定 SPE 作为基准；它否定的是「CKR 已是共同知识」这一经验主张。</p><p>共同知识是「我知道你知道……」的无限层。有限层理性（我知道你理性，但不确定你知道我理性）已经足以在蜈蚣里撑住前几步「过」。归纳需要的是无限层在每一个节点上还在。实验室与逻辑都在说：无限层太贵。</p><p><span class="marginnote">常见误区：把实验里人们晚停读成「SPE 被推翻了」。被质疑的是「共同知识理性真实存在」这条经验假设，不是 SPE 的定义本身；只要给对方一点点是「合作类型」的概率，长时间合作自己就能成为均衡。</span></p><p>后课默认：有限完美信息树上 SPE 仍是基准解；把它读成共同知识理性的必然，蜈蚣显示过强。无限重复将把 SPE 集合撑大，那是另一限度：不是太瘦，是太肥。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SPE 要求未达子博弈也是纳什；CKR 在根上不必给未达节点继续赋值。</li><li>蜈蚣把「过」写成对归纳的偏离，到达与 CKR 冲突。</li><li>脆的是认知推论，不是 SPE 定义自相矛盾。</li><li>少量类型或不完美信息即可改变归纳路径。</li><li>出处：Rosenthal, <em>JET</em>, 1981；Reny, <em>GEB</em>, 1993；Aumann, <em>GEB</em>, 1995。</li></ul>',11))])}const S=l(p,[["render",m]]);export{F as __pageData,S as default};
